pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value <= address(c).balance + 1 ether); // Ensure enough balance for any transaction

        // Fund the contract to allow sendMoney to trigger fallback
        vm.deal(address(c), 1 ether);

        uint256 oldCount = c.depositsCount();

        // Call sendMoney; this triggers the fallback on the target
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // The rule: if sendMoney succeeded and the target is a contract that does not revert, depositsCount increments by 1
        if (success) {
            assertTrue(c.depositsCount() == oldCount + 1);
        } else {
            // If sendMoney failed (e.g., target reverts), depositsCount stays the same
            assertTrue(c.depositsCount() == oldCount);
        }
    }
}

