pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // Bound value to avoid overflow issues
        _value = bound(_value, 1, 1 ether);
        // Ensure target is not owner (so we can simulate a contract that reverts on receive)
        vm.assume(_target != address(c.owner()));

        // Deploy a dummy contract that has no receive/fallback to force fallback on C
        address dummy = address(new DummyRevert());

        // Record initial depositsCount
        uint256 before = c.depositsCount();

        // Fund the contract with enough balance
        vm.deal(address(c), _value);

        // Call sendMoney with non-zero value to dummy (will trigger fallback in C)
        // Use prank to call as owner
        vm.prank(c.owner());
        c.sendMoney(dummy, _value);

        // After call, depositsCount should have increased by exactly 1 because fallback was triggered
        assertTrue(c.depositsCount() == before + 1, "depositsCount should increase by 1 when fallback is triggered");
    }
}

