import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 value) public {
        vm.assume(initialBalance >= 0 && value >= 0);
        // Set up initial balances
        vm.deal(address(c), initialBalance);
        vm.deal(caller, 1 ether); // give caller some ETH to potentially use

        uint256 balanceBefore = address(c).balance;

        // Call sendMoney as the given caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, address(0x1234), value));

        // The general rule: if the call was successful and the caller is NOT the owner,
        // the contract balance must remain unchanged (because the modifier should block non-owners).
        // If the caller IS the owner, the balance may decrease (if value <= balance) or revert (if value > balance).
        // We express the rule: either the call reverted (success == false) OR the caller is owner OR balance unchanged.
        address owner = c.owner();
        bool callerIsOwner = (caller == owner);
        uint256 balanceAfter = address(c).balance;
        bool balanceUnchanged = (balanceAfter == balanceBefore);

        assertTrue(success == false || callerIsOwner || balanceUnchanged);
    }
}

